import React, { useState } from 'react';
import { ComposeEmail } from './Components/ComposeEmail';
import { EmailDetail } from './Components/EmailDetail';
import { EmailList } from './Components/EmailList';
// import './App.css';

export function App() {

  const [emails, setEmails] = useState([
    { id: 1, subject: 'Hello', sender: 'example@example.com', body: 'This is a test email' },
    { id: 2, subject: 'Meeting', sender: 'me@me.com', body: 'Let\'s meet tomorrow' },
  ]);

  const [selectedEmail, setSelectedEmail] = useState<{ id: number; subject: string; sender: string; body: string } | null>(null);

  const handleSend = (subject: string, body: string) => {
    const newEmail = { id: emails.length + 1, subject, body, sender: 'you@you.com' };
    setEmails([...emails, newEmail]);
  };

  const handleSelectEmail = (email: { id: number; subject: string; sender: string; body: string }) => {
    setSelectedEmail(email);
  };

  return (
    <div className="App">
      <h1>Emailify</h1>
      <ComposeEmail onsend={handleSend} />
      <EmailList email={emails.map(e => ({ ...e, date: new Date().toISOString(), avatarUrL: 'https://via.placeholder.com/40', isRead: false
      }))} onSelectEmail={(id) => { const email = emails.find(e => e.id === id); if (email) handleSelectEmail(email); }} selectedEmailid={selectedEmail?.id || null} />
      <EmailDetail email={selectedEmail ? { ...selectedEmail,
        date: new Date().toISOString(),
        avatarUrL: 'https://via.placeholder.com/40',
        isRead: false
      } : null} />
    </div>
  );
}
